#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
#include <math.h>
static void ok(BOOL v,NSString*s){if(!v){fprintf(stderr,"FAIL %s\n",s.UTF8String);exit(1);}}
int main(int argc,const char**argv){@autoreleasepool{ok(argc==3,@"usage: check source probe");NSError*err=nil;id<MTLDevice>d=MTLCreateSystemDefaultDevice();ok(d!=nil,@"Metal unavailable");NSString*s=[NSString stringWithContentsOfFile:@(argv[1]) encoding:NSUTF8StringEncoding error:&err];s=[s stringByAppendingString:[NSString stringWithContentsOfFile:@(argv[2]) encoding:NSUTF8StringEncoding error:&err]];MTLCompileOptions*opts=[MTLCompileOptions new];opts.languageVersion=MTLLanguageVersion3_0;id<MTLLibrary>lib=[d newLibraryWithSource:s options:opts error:&err];ok(lib!=nil,err.description);id<MTLComputePipelineState>p=[d newComputePipelineStateWithFunction:[lib newFunctionWithName:@"lava_probe"] error:&err];ok(p!=nil,err.description);id<MTLCommandQueue>q=[d newCommandQueue];
for(int empty=0;empty<2;empty++){float l[280]={0};float bounds[8]={.2,.2,.4,.4,.6,.2,.8,.4};if(!empty)memcpy(l+1088/4,bounds,sizeof bounds);id<MTLBuffer>o=[d newBufferWithLength:256*16 options:MTLResourceStorageModeShared];id<MTLCommandBuffer>b=[q commandBuffer];id<MTLComputeCommandEncoder>e=[b computeCommandEncoder];[e setComputePipelineState:p];[e setBuffer:o offset:0 atIndex:0];[e setBytes:l length:sizeof l atIndex:17];[e dispatchThreads:MTLSizeMake(256,1,1) threadsPerThreadgroup:MTLSizeMake(32,1,1)];[e endEncoding];[b commit];[b waitUntilCompleted];ok(b.status==MTLCommandBufferStatusCompleted,b.error.description);float*v=o.contents;for(int i=0;i<256;i++){float u=i/255.f;BOOL hit=!empty&&((u>=.2f&&u<.4f)||(u>=.6f&&u<.8f));ok((v[i*4+3]>0)==hit,@"atlas classification");for(int c=0;c<3;c++){ok(isfinite(v[i*4+c])&&v[i*4+c]>=0&&v[i*4+c]<6,@"bounded emission");if(i)ok(v[i*4+c]>=v[(i-1)*4+c],@"monotonic heat");}}ok(v[255*4]>3&&v[0]>.2,@"self emission range");}printf("PASS 512 lava samples: atlas identity, empty bounds, smooth heat and bounded emission\n");}return 0;}
